# Let me check the dialogs that the LLM classified as YES but don't contain billing keywords
billing_problem_keywords_set = {'payment', 'billing', 'charge', 'charged', 'refund', 
                            'overcharged', 'unauthorized', 'wallet', 'funds',
                            'credit card', 'debit card', 'transaction'}

yes_no_keyword = []
yes_with_keyword = []

for i, (d, r) in enumerate(zip(dataset, all_results)):
    if 'YES' in r.upper().strip()[:10]:
        dialog_lower = d['dialog'].lower()
        has_keyword = any(kw in dialog_lower for kw in billing_problem_keywords_set)
        if has_keyword:
            yes_with_keyword.append(d)
        else:
            yes_no_keyword.append(d)

print(f"YES with billing keyword: {len(yes_with_keyword)}")
print(f"YES without billing keyword: {len(yes_no_keyword)}")
print(f"\nSample of YES without billing keywords:")
